// recipe: drag-state
// args: none
// returns: ok, paused, minigame, timeScale, dragItem, backpackOpen, focusedSteamId, error, detail
//
// Reads the state the cross-player drag chain turns on: whether the game is paused or in a minigame (its drag handler returns early
// in both cases), its OWN dragged item (`PlayerCamera.main.dragItem`, set by `TryPickupFromUI` when the `iteminteract` key fires
// while the pointer is over an `InvButton`/`ItemLabel`), and the CUO side of the cue (`RemoteBackpackView`). One top-level expression.
((System.Func<string>)(() => { var services = CasualtiesUnknownOnline.Runtime.CuoBootstrap.Services; if (services == null) { return "{\"ok\":false,\"error\":\"no-services\"}"; } var camera = PlayerCamera.main; if (camera == null) { return "{\"ok\":false,\"error\":\"no-camera\"}"; } var item = camera.dragItem; var itemId = item == null ? "" : item.id; var paused = PauseHandler.paused; var minigame = MinigameBase.main != null && MinigameBase.main.currentMinigame; var viewType = (System.Type)null; var asms = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < asms.Length; i++) { if (viewType == null) { try { viewType = asms[i].GetType("CasualtiesUnknownOnline.GameAdapter.Items.RemoteBackpackView", false); } catch { viewType = null; } } } var isOpen = false; var focused = "0"; if (viewType != null) { var openProperty = viewType.GetProperty("IsOpen", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static); if (openProperty != null) { isOpen = (bool)openProperty.GetValue(null); } var focusedProperty = viewType.GetProperty("FocusedSteamId", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static); if (focusedProperty != null) { focused = focusedProperty.GetValue(null).ToString(); } } return "{\"ok\":true,\"paused\":" + (paused ? "true" : "false") + ",\"minigame\":" + (minigame ? "true" : "false") + ",\"timeScale\":" + UnityEngine.Time.timeScale.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture) + ",\"dragItem\":\"" + itemId + "\",\"backpackOpen\":" + (isOpen ? "true" : "false") + ",\"focusedSteamId\":\"" + focused + "\"}"; }))()